-- VERIFICAÇÃO ESTRUTURAL da migration 20261110100000 (somente leitura). Roda no clone PROD-equivalente e no DEV.
-- Imprime uma linha por verificação: "OK|FALHA · descrição · detalhe".
\pset tuples_only on
\pset format unaligned
with
chk(nome, ok, detalhe) as (
  select 'tabelas novas existem (9)', count(*) = 9, count(*)::text from information_schema.tables where table_schema='public' and table_name in ('escala_buffers_fisicos','escala_buffer_pares','escala_buffer_dispensas','escala_buffer_maquinas','escala_fechamento_aberturas','escala_fechamentos','escala_fechamento_buffers','escala_fechamento_log','escala_fechamento_trava')
  union all select 'views novas existem (8)', count(*) = 8, count(*)::text from information_schema.views where table_schema='public' and table_name in ('escala_fechamentos_vigentes','escala_fechamento_estado','escala_contagens_fechamento_para_motor','escala_wip_erro','escala_wip_erro_dia','escala_wip_erro_maquina','escala_wip_erro_produto','escala_fechamento_duracao')
  union all select 'RLS ligado em TODAS as tabelas novas', bool_and(c.relrowsecurity), count(*)::text || ' tabelas' from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in ('escala_buffers_fisicos','escala_buffer_pares','escala_buffer_dispensas','escala_buffer_maquinas','escala_fechamento_aberturas','escala_fechamentos','escala_fechamento_buffers','escala_fechamento_log','escala_fechamento_trava')
  union all select 'policy de leitura em cada tabela nova', count(distinct tablename) = 9, count(distinct tablename)::text from pg_policies where schemaname='public' and policyname like '%_leitura' and tablename in ('escala_buffers_fisicos','escala_buffer_pares','escala_buffer_dispensas','escala_buffer_maquinas','escala_fechamento_aberturas','escala_fechamentos','escala_fechamento_buffers','escala_fechamento_log','escala_fechamento_trava')
  union all select 'authenticated/anon NÃO têm escrita nas tabelas novas', not exists (select 1 from information_schema.role_table_grants g where g.table_schema='public' and g.grantee in ('anon','authenticated') and g.privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE') and g.table_name in ('escala_buffers_fisicos','escala_buffer_pares','escala_buffer_dispensas','escala_buffer_maquinas','escala_fechamento_aberturas','escala_fechamentos','escala_fechamento_buffers','escala_fechamento_log','escala_fechamento_trava')), 'sem grants de escrita'
  union all select 'service_role só INSERT nas tabelas append-only', not exists (select 1 from information_schema.role_table_grants g where g.table_schema='public' and g.grantee='service_role' and g.privilege_type in ('UPDATE','DELETE','TRUNCATE') and g.table_name in ('escala_fechamentos','escala_fechamento_buffers','escala_fechamento_log','escala_fechamento_aberturas')), 'imutáveis também por privilégio'
  union all select 'RPCs só para service_role (sem execute para public/anon/authenticated)', not exists (select 1 from information_schema.routine_privileges r where r.routine_schema='public' and r.routine_name in ('escala_fechamento_registrar','escala_fechamento_abrir','escala_fechamento_resultado','escala_fechamento_trava_adquirir','escala_fechamento_trava_liberar','escala_fechamento_apontamento_permitido','escala_fechamento_paradas','escala_fechamento_corte_liberado') and r.grantee in ('PUBLIC','anon','authenticated')), 'execute restrito'
  union all select 'funções novas existem (RPCs + helpers)', count(*) >= 9, count(*)::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('escala_fechamento_registrar','escala_fechamento_abrir','escala_fechamento_resultado','escala_fechamento_trava_adquirir','escala_fechamento_trava_liberar','escala_fechamento_apontamento_permitido','escala_fechamento_paradas','escala_fechamento_corte_liberado','escala_fechamento_fisico_modo','escala_trg_apontamento_fechamento')
  union all select 'triggers de imutabilidade (update/delete e truncate) nas 4 tabelas append-only', count(*) = 8, count(*)::text from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and t.tgname like 'trg_escala_fechamento%imutavel%'
  union all select 'trigger de apontamento instalado em apontamentos_producao', exists (select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relname='apontamentos_producao' and t.tgname='trg_apontamentos_producao_fechamento' and not t.tgisinternal), 'before insert'
  union all select 'índices das tabelas novas', count(*) >= 9, count(*)::text from pg_indexes where schemaname='public' and tablename in ('escala_fechamentos','escala_fechamento_buffers','escala_fechamento_log','escala_fechamento_aberturas','escala_buffer_pares','escala_buffers_fisicos')
  union all select 'FKs das tabelas novas (todas validadas)', bool_and(convalidated) and count(*) > 0, count(*)::text from pg_constraint where contype='f' and conrelid::regclass::text in ('escala_fechamentos','escala_fechamento_buffers','escala_fechamento_log','escala_fechamento_aberturas','escala_buffer_pares','escala_buffer_dispensas','escala_buffer_maquinas')
  union all select 'CHECK de permissões preserva as existentes + as 2 novas', pg_get_constraintdef(oid) like '%escala_fechamento_excecao%' and pg_get_constraintdef(oid) like '%escala_fechamento,%' or pg_get_constraintdef(oid) like '%escala_fechamento}%' and pg_get_constraintdef(oid) like '%escala_relatorios%', 'escala_relatorios + novas' from pg_constraint where conname='usuario_permissoes_permissao_check'
  union all select 'CHECK de eventos aceita fechamento_fisico e preserva os tipos', pg_get_constraintdef(oid) like '%fechamento_fisico%' and pg_get_constraintdef(oid) like '%apontamento_periodo%' and pg_get_constraintdef(oid) like '%geracao_semanal%', 'tipos' from pg_constraint where conname='escala_producao_eventos_tipo_check'
  union all select 'claim da outbox reivindica fechamento_fisico e mantém os tipos antigos', pg_get_functiondef(p.oid) like '%fechamento_fisico%' and pg_get_functiondef(p.oid) like '%geracao_manual%' and pg_get_functiondef(p.oid) like '%recurso_liberado%', 'definição alterada' from pg_proc p where p.proname='escala_reivindicar_eventos'
  union all select 'guarda do histórico: UMA condição alterada, resto igual', pg_get_functiondef(p.oid) like '%if v_inicio_corte <= now() and not public.escala_fechamento_corte_liberado(p_a_partir_data, p_a_partir_periodo) then%' and (length(pg_get_functiondef(p.oid)) - length(replace(pg_get_functiondef(p.oid), 'escala_fechamento_corte_liberado', ''))) / length('escala_fechamento_corte_liberado') = 1, 'ocorrências do helper = 1' from pg_proc p where p.proname='escala_aplicar_recalculo' and exists (select 1 from pg_proc q where q.proname='escala_aplicar_recalculo' having count(*)=1)
  union all select 'flag escala_fechamento_fisico_modo existe e é válida', exists (select 1 from escala_parametros where chave='escala_fechamento_fisico_modo' and valor in ('"desligado"'::jsonb,'"sombra"'::jsonb,'"ativo"'::jsonb)), coalesce((select valor::text from escala_parametros where chave='escala_fechamento_fisico_modo'), 'ausente')
  union all select 'gatilho de parâmetros ignora a flag (ligar/desligar não dispara recálculo)', pg_get_functiondef(p.oid) like '%a flag do fechamento físico nunca dispara recálculo%', 'saída antecipada' from pg_proc p where p.proname='escala_trg_parametros'
  union all select 'append-only: UPDATE em fechamentos é recusado', (select count(*) from pg_trigger t where t.tgrelid='public.escala_fechamentos'::regclass and not t.tgisinternal) >= 2, 'trigger presente'
)
select (case when ok then 'OK    ' else 'FALHA ' end) || nome || ' · ' || coalesce(detalhe, '') from chk;
